#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;
    vector<vector<long long>> ev(n, vector<long long>(2));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> ev[i][j];
        }
    }

    vector<long long> starts(n), ends(n);
    for (int k = 0; k < n; k++) {
        starts[k] = ev[k][0];
        ends[k] = ev[k][1];
    }
    sort(starts.begin(), starts.end());
    sort(ends.begin(), ends.end());
    int i = 0, j = 0, cur = 0, best = 0;
    while (i < n) {
        if (starts[i] < ends[j]) {
            cur++;
            i++;
            best = max(best, cur);
        } else {
            cur--;
            j++;
        }
    }
    cout << best << "\n";

    return 0;
}

